/** Family WhatsApp message. Only facts from the official record. */
export function familyMessage(lang: Lang, o: { level: "RED" | "AMBER"; who?: string; name: string; batch: string; month: string; link: string }): string {
  if (lang === "hi") {
    return [
      o.level === "RED" ? "दवा कवच: सरकारी चेतावनी मिली" : "दवा कवच: मिलती-जुलती सरकारी चेतावनी मिली",
      o.who ? `किसके लिए: ${o.who}` : "",
      `दवा: ${o.name}`,
      `बैच: ${o.batch}`,
      `CDSCO चेतावनी: ${o.month}`,
      o.level === "RED"
        ? "अगली खुराक से पहले फार्मासिस्ट या डॉक्टर से बात करें। ज़रूरी दवा अचानक बंद न करें।"
        : "कृपया बैच नंबर मिलाएँ और फार्मासिस्ट से पूछें।",
      `स्रोत: ${o.link}`,
    ].filter(Boolean).join("\n");
  }
  return [
    o.level === "RED" ? "DawaShield: official alert found" : "DawaShield: possible match with an official alert",
    o.who ? `For: ${o.who}` : "",
    `Medicine: ${o.name}`,
    `Batch: ${o.batch}`,
    `CDSCO alert: ${o.month}`,
    o.level === "RED"
      ? "Please speak to a pharmacist or doctor before the next dose. Do not stop an important medicine suddenly."
      : "Please check the batch number and ask a pharmacist.",
    `Source: ${o.link}`,
  ].filter(Boolean).join("\n");
}

/** Pre-filled complaint text for the official channel. */
export function complaintMessage(lang: Lang, o: { name: string; batch: string; manufacturer?: string; expiry?: string; level: string; month?: string }): string {
  if (lang === "hi") {
    return [
      "विषय: संदिग्ध / चेतावनी सूची वाली दवा की सूचना",
      `दवा का नाम: ${o.name}`,
      `बैच नंबर: ${o.batch}`,
      o.manufacturer ? `निर्माता (लेबल पर): ${o.manufacturer}` : "",
      o.expiry ? `समाप्ति तिथि: ${o.expiry}` : "",
      o.month ? `मिलती CDSCO चेतावनी: ${o.month}` : "",
      "खरीदने की जगह और तारीख़: ",
      "मेरा नाम और फ़ोन: ",
    ].filter(Boolean).join("\n");
  }
  return [
    "Subject: Reporting a suspected / alert-listed medicine",
    `Medicine name: ${o.name}`,
    `Batch number: ${o.batch}`,
    o.manufacturer ? `Manufacturer (as on label): ${o.manufacturer}` : "",
    o.expiry ? `Expiry: ${o.expiry}` : "",
    o.month ? `Matching CDSCO alert: ${o.month}` : "",
    "Where and when bought: ",
    "My name and phone: ",
  ].filter(Boolean).join("\n");
}

